import subprocess, json

def act(turn, move):
    res = subprocess.run(["python3", "/app/act.py", json.dumps({"turn_deg": turn, "move_m": move})], capture_output=True, text=True)
    print(res.stdout)
    return json.loads(res.stdout)

# Turn 45 degrees, 7 times to see 45, 90, 135, 180, 225, 270, 315
for i in range(7):
    act(45, 0.0)
